import Foundation
import Security

@MainActor final class OnlineServices {
 private let library:LocalLibrary
 private let service:String
 private var requests:[String:URLSessionDataTask]=[:]
 private let models=["qwen/qwen3.8-27b","openai/gpt-oss-120b","openai/gpt-oss-20b"]
 init(library:LocalLibrary){self.library=library;service="com.rohaniyer.jyotish.online"+(ProcessInfo.processInfo.environment["JYOTISH_TEST_DATA"] == nil ? "":".qa")}
 private func query(_ provider:String)->[String:Any]{[kSecClass as String:kSecClassGenericPassword,kSecAttrService as String:service,kSecAttrAccount as String:provider]}
 private func key(_ provider:String)->String?{var q=query(provider);q[kSecReturnData as String]=true;q[kSecMatchLimit as String]=kSecMatchLimitOne;var result:CFTypeRef?;guard SecItemCopyMatching(q as CFDictionary,&result)==errSecSuccess,let data=result as? Data else{return nil};return String(data:data,encoding:.utf8)}
 private func saveKey(_ provider:String,_ value:String)throws{guard value.count<=512,!value.contains("\n"),!value.contains("\r") else{throw LocalFailure(message:"Invalid API key.")};let q=query(provider);if value.isEmpty{SecItemDelete(q as CFDictionary);return};let attrs=[kSecValueData as String:Data(value.utf8)];let status=SecItemUpdate(q as CFDictionary,attrs as CFDictionary);if status==errSecItemNotFound{var add=q;add[kSecValueData as String]=Data(value.utf8);add[kSecAttrAccessible as String]=kSecAttrAccessibleAfterFirstUnlockThisDeviceOnly;guard SecItemAdd(add as CFDictionary,nil)==errSecSuccess else{throw LocalFailure(message:"Could not save the key in macOS Keychain.")}}else if status != errSecSuccess{throw LocalFailure(message:"Could not update the key in macOS Keychain.")}}
 func config()->[String:Any]{var p=(library.read("online-settings.json") as? [String:Any]) ?? [:];p["hasGroqKey"]=key("groq") != nil;p["hasElevenKey"]=key("eleven") != nil;p["keyStorage"]="macOS Keychain";return p}
 func save(_ input:[String:Any])throws->[String:Any]{if let k=input["groqKey"] as? String,!k.isEmpty{try saveKey("groq",k.trimmingCharacters(in:.whitespacesAndNewlines))};if let k=input["elevenKey"] as? String,!k.isEmpty{try saveKey("eleven",k.trimmingCharacters(in:.whitespacesAndNewlines))};if input["clearGroq"] as? Bool==true{try saveKey("groq","")};if input["clearEleven"] as? Bool==true{try saveKey("eleven","")};let model=input["model"] as? String ?? models[0];guard models.contains(model) else{throw LocalFailure(message:"Choose a supported online model.")};let voice=input["voiceId"] as? String ?? "";guard voice.range(of:"^[a-zA-Z0-9_-]{0,80}$",options:.regularExpression) != nil else{throw LocalFailure(message:"Invalid voice ID.")};try library.write(["model":model,"voiceId":voice,"onlineConsent":input["onlineConsent"] as? Bool ?? false,"voiceConsent":input["voiceConsent"] as? Bool ?? false],"online-settings.json");return config()}
 func cancel(){for task in requests.values{task.cancel()};requests.removeAll()}
 private func request(_ provider:String,_ route:String,_ method:String="GET",_ body:[String:Any]?=nil)async throws->Data{
  guard let secret=key(provider) else{throw LocalFailure(message:"Add your \(provider == "groq" ? "Groq":"ElevenLabs") API key in reading settings.")}
  let origin=provider=="groq" ? "https://api.groq.com":"https://api.elevenlabs.io";var req=URLRequest(url:URL(string:origin+route)!,timeoutInterval:120);req.httpMethod=method;req.setValue(provider=="groq" ? "Bearer "+secret:secret,forHTTPHeaderField:provider=="groq" ? "Authorization":"xi-api-key");if let body{req.setValue("application/json",forHTTPHeaderField:"Content-Type");req.httpBody=try JSONSerialization.data(withJSONObject:body)}
  let id=UUID().uuidString
  return try await withCheckedThrowingContinuation{continuation in
   let task=URLSession.shared.dataTask(with:req){[weak self] bytes,response,error in Task{@MainActor in self?.requests.removeValue(forKey:id);if let error{continuation.resume(throwing:error);return};guard let http=response as? HTTPURLResponse,(200..<300).contains(http.statusCode),let bytes else{let code=(response as? HTTPURLResponse)?.statusCode ?? 0;continuation.resume(throwing:LocalFailure(message:"\(provider == "groq" ? "Groq":"ElevenLabs") request failed (HTTP \(code)). \(code==429 ? "Your account quota or rate limit was reached.":code==401 ? "Check your API key.":"Check your account access and credits.")"));return};continuation.resume(returning:bytes)}};requests[id]=task;task.resume()
  }
 }
 func answer(_ input:[String:Any])async throws->String{let settings=config();guard settings["onlineConsent"] as? Bool==true else{throw LocalFailure(message:"Enable online sharing in reading settings first.")};guard let prompt=input["prompt"] as? String,prompt.count<=80000,let schema=input["schema"] as? [String:Any] else{throw LocalFailure(message:"Invalid online reading.")};let model=settings["model"] as? String ?? models[0];let body:[String:Any]=["model":model,"messages":[["role":"user","content":prompt]],"temperature":0.2,"max_completion_tokens":2400,"reasoning_effort":"low","stream":false,"response_format":["type":"json_schema","json_schema":["name":"jyotish_consultation","strict":true,"schema":schema]]];let bytes=try await request("groq","/openai/v1/chat/completions","POST",body);guard let object=try JSONSerialization.jsonObject(with:bytes) as? [String:Any],let choices=object["choices"] as? [[String:Any]],let message=choices.first?["message"] as? [String:Any],let text=message["content"] as? String,!text.isEmpty else{throw LocalFailure(message:"Groq returned no completed reading.")};return text}
 func voices()async throws->Any{let bytes=try await request("eleven","/v2/voices?page_size=100");let data=try JSONSerialization.jsonObject(with:bytes) as? [String:Any];return (data?["voices"] as? [[String:Any]] ?? []).map{["id":$0["voice_id"] ?? "","name":$0["name"] ?? "Voice","labels":$0["labels"] ?? [:]]}}
 func token()async throws->Any{guard config()["voiceConsent"] as? Bool==true else{throw LocalFailure(message:"Enable voice sharing in reading settings first.")};return try JSONSerialization.jsonObject(with:await request("eleven","/v1/single-use-token/realtime_scribe","POST",[:]))}
 func speak(_ input:[String:Any])async throws->Any{let settings=config();guard settings["voiceConsent"] as? Bool==true,let voice=settings["voiceId"] as? String,!voice.isEmpty,let text=input["text"] as? String,!text.isEmpty,text.count<=1000 else{throw LocalFailure(message:"Choose a voice and enable voice sharing first.")};let bytes=try await request("eleven","/v1/text-to-speech/\(voice)/stream?output_format=mp3_22050_32","POST",["text":text,"model_id":"eleven_flash_v2_5","voice_settings":["stability":0.65,"similarity_boost":0.75,"speed":0.92]]);return ["audio":bytes.base64EncodedString(),"mime":"audio/mpeg"]}
}
